import{_ as t,c as r,o as s,ae as d}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Folder Structure","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/customization/folder-structure.md","filePath":"api/workflows/customization/folder-structure.md"}'),o={name:"api/workflows/customization/folder-structure.md"};function a(i,e,n,c,p,l){return s(),r("div",null,e[0]||(e[0]=[d(`<h1 id="folder-structure" tabindex="-1">Folder Structure <a class="header-anchor" href="#folder-structure" aria-label="Permalink to &quot;Folder Structure&quot;">​</a></h1><p>Every API resource is the same five files plus lang and tests. Each has one job.</p><p>The Model declares the endpoints. Reads go through a Provider, writes through a Processor, and both hit the core repository:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  model[Model&lt;br/&gt;declares REST + GraphQL ops] --&gt; prov[Provider&lt;br/&gt;read path]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  model --&gt; proc[Processor&lt;br/&gt;write path]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dto[DTO&lt;br/&gt;typed input] --&gt; proc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prov --&gt; repo[(Core repository)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  proc --&gt; repo</span></span></code></pre></div><p><code>lang</code> strings and the two test files hang off each resource — see the table below.</p><table tabindex="0"><thead><tr><th>Unit</th><th>Path shape</th><th>Responsibility</th></tr></thead><tbody><tr><td>Model</td><td><code>src/*/Models/*.php</code></td><td><code>#[ApiResource]</code> — declares REST + GraphQL operations and the OpenAPI block</td></tr><tr><td>DTO</td><td><code>src/*/Dto/*Input.php</code></td><td>Typed input contract (validation surface + GraphQL input type)</td></tr><tr><td>Provider</td><td><code>src/*/State/*Provider.php</code></td><td>Read path: auth, query, response envelope</td></tr><tr><td>Processor</td><td><code>src/*/State/*Processor.php</code></td><td>Write path: validation, core repo call, events, permission gate</td></tr><tr><td>Resolver</td><td><code>src/*/Resolver/*.php</code></td><td>GraphQL custom query resolver (only when needed)</td></tr><tr><td>lang</td><td><code>Resources/lang/en/app.php</code></td><td>All user-facing strings (single-file convention)</td></tr><tr><td>tests</td><td><code>tests/Feature/{RestApi,GraphQL}/*Test.php</code></td><td>Lock both transports</td></tr></tbody></table><p>Shop resources live under <code>src/{Models,Dto,State}</code>. New collection/item providers extend the shared abstract base providers — reuse, don&#39;t re-scaffold.</p><h2 id="admin-resources-are-different" tabindex="-1">Admin resources are different <a class="header-anchor" href="#admin-resources-are-different" aria-label="Permalink to &quot;Admin resources are different&quot;">​</a></h2><p>Admin uses the same file roles, but everything lives under <code>src/Admin/**</code> and every class is prefixed <code>Admin</code> (e.g. <code>AdminAttributeProcessor</code>). Two differences to know:</p><p><strong>The read path is split into two providers</strong>, not one:</p><table tabindex="0"><thead><tr><th>File</th><th>Path shape</th><th>Job</th></tr></thead><tbody><tr><td>Collection provider</td><td><code>src/Admin/State/Admin*CollectionProvider.php</code></td><td>List (filter, sort, paginate)</td></tr><tr><td>Item provider</td><td><code>src/Admin/State/Admin*ItemProvider.php</code></td><td>Single record read</td></tr><tr><td>Processor</td><td><code>src/Admin/State/Admin*Processor.php</code></td><td>Write (create / update)</td></tr><tr><td>Mass-delete processor</td><td><code>src/Admin/State/Admin*MassDeleteProcessor.php</code></td><td>Bulk delete</td></tr></tbody></table><p><strong>Admin has extra folders</strong> shop doesn&#39;t:</p><ul><li><code>src/Admin/Rules/</code> — validation rule classes (shop keeps these in <code>src/Validators/</code>).</li><li><code>src/Admin/DataGrids/</code> — list filter/sort/pagination definitions backing the collection providers.</li></ul><p>Keep the shop and admin trees separate.</p>`,14)]))}const m=t(o,[["render",a]]);export{u as __pageData,m as default};
